import{_ as e,o as r,c as t,a2 as n}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_09_backup_spectrum.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_09_n_step_return.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_09_reward_propagation.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_09_lambda_weights.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_09_eligibility_trace.png",f=JSON.parse('{"title":"奖励隔了十步才出现，前面的动作怎么分功？n 步 TD 与资格迹讲透了","description":"一步时序差分只把当前误差写回最近的状态，蒙特卡洛却要等完整回合结束后，才把最终回报交给整条轨迹。两者之间并不是空白地带。n-step Temporal-Difference Learning（n 步时序差分学习）向未来多看若干步，再从末端价值自举；TD(λ) 则把不同步长的回报加权组合，并用 Eli","frontmatter":{"title":"奖励隔了十步才出现，前面的动作怎么分功？n 步 TD 与资格迹讲透了","description":"一步时序差分只把当前误差写回最近的状态，蒙特卡洛却要等完整回合结束后，才把最终回报交给整条轨迹。两者之间并不是空白地带。n-step Temporal-Difference Learning（n 步时序差分学习）向未来多看若干步，再从末端价值自举；TD(λ) 则把不同步长的回报加权组合，并用 Eli","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":19,"source":"2026-08-13/rl_series_09_n_step_td_eligibility_traces.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_09_backup_spectrum.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-09-n-step-td-eligibility-traces"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"奖励隔了十步才出现，前面的动作怎么分功？n 步 TD 与资格迹讲透了"}],["meta",{"property":"og:description","content":"一步时序差分只把当前误差写回最近的状态，蒙特卡洛却要等完整回合结束后，才把最终回报交给整条轨迹。两者之间并不是空白地带。n-step Temporal-Difference Learning（n 步时序差分学习）向未来多看若干步，再从末端价值自举；TD(λ) 则把不同步长的回报加权组合，并用 Eli"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-09-n-step-td-eligibility-traces"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_09_backup_spectrum.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"奖励隔了十步才出现，前面的动作怎么分功？n 步 TD 与资格迹讲透了"}],["meta",{"name":"twitter:description","content":"一步时序差分只把当前误差写回最近的状态，蒙特卡洛却要等完整回合结束后，才把最终回报交给整条轨迹。两者之间并不是空白地带。n-step Temporal-Difference Learning（n 步时序差分学习）向未来多看若干步，再从末端价值自举；TD(λ) 则把不同步长的回报加权组合，并用 Eli"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_09_backup_spectrum.png"}]],"prev":{"text":"行为在探索，目标却贪心：Q-learning 为什么能“边走边学最优”","link":"/rl/rl-series-08-q-learning"},"next":{"text":"一张 Q 表装不下真实世界：函数逼近怎样让强化学习学会泛化","link":"/rl/rl-series-10-function-approximation"}},"headers":[],"relativePath":"rl/rl-series-09-n-step-td-eligibility-traces.md","filePath":"rl/rl-series-09-n-step-td-eligibility-traces.md","lastUpdated":null}'),d={name:"rl/rl-series-09-n-step-td-eligibility-traces.md"};function p(c,a,_,u,b,m){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="奖励隔了十步才出现-前面的动作怎么分功-n-步-td-与资格迹讲透了" tabindex="-1">奖励隔了十步才出现，前面的动作怎么分功？n 步 TD 与资格迹讲透了 <a class="header-anchor" href="#奖励隔了十步才出现-前面的动作怎么分功-n-步-td-与资格迹讲透了" aria-label="Permalink to &quot;奖励隔了十步才出现，前面的动作怎么分功？n 步 TD 与资格迹讲透了&quot;">​</a></h1><p>一步时序差分只把当前误差写回最近的状态，蒙特卡洛却要等完整回合结束后，才把最终回报交给整条轨迹。两者之间并不是空白地带。n-step Temporal-Difference Learning（n 步时序差分学习）向未来多看若干步，再从末端价值自举；TD(λ) 则把不同步长的回报加权组合，并用 Eligibility Trace（资格迹）把当前误差分配给近期访问过的状态或动作。</p><p>这组方法真正解决的是 Credit Assignment（信用分配）问题：一次迟到的奖励或惩罚出现时，沿途哪些决策应承担多少责任。它们不是让智能体获得因果推理能力，而是提供一种时间上的责任分配机制。距离越近、访问越频繁的状态动作通常留下更强痕迹，因此能从当前时序差分误差获得更大更新。</p><p>理解这一篇，需要同时看见两个方向。前向视角从某个状态向未来收集多步奖励，适合定义学习目标；后向视角从当前误差回看近期轨迹，适合在线实现。n 和 λ 都在控制信息传播尺度，但含义不同，也不能脱离学习率、折扣、终止语义和策略差异单独调节。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-n-步回报位于单步-td-与蒙特卡洛之间" tabindex="-1">1.1 n 步回报位于单步 TD 与蒙特卡洛之间 <a class="header-anchor" href="#_1-1-n-步回报位于单步-td-与蒙特卡洛之间" aria-label="Permalink to &quot;1.1 n 步回报位于单步 TD 与蒙特卡洛之间&quot;">​</a></h3><p>当 (n=1) 时，只观察一个奖励便从下一状态价值自举；当 (n) 延伸到回合终点时，不再需要末端自举，行为接近蒙特卡洛。有限的中间步长混合了真实多步奖励与末端估计。</p><h3 id="_1-2-更大的-n-不保证更好" tabindex="-1">1.2 更大的 n 不保证更好 <a class="header-anchor" href="#_1-2-更大的-n-不保证更好" aria-label="Permalink to &quot;1.2 更大的 n 不保证更好&quot;">​</a></h3><p>增大 n 往往减少对早期价值估计的依赖，却引入更多随机奖励、动作和转移，增加目标方差、更新延迟与缓存开销。合适步长取决于任务时延、轨迹长度、奖励噪声和学习率。</p><h3 id="_1-3-λ-回报不是挑选一个固定步长" tabindex="-1">1.3 λ 回报不是挑选一个固定步长 <a class="header-anchor" href="#_1-3-λ-回报不是挑选一个固定步长" aria-label="Permalink to &quot;1.3 λ 回报不是挑选一个固定步长&quot;">​</a></h3><p>Lambda Return（λ 回报）对一步、两步、三步直到更长回报进行指数加权。λ 越接近零，权重越集中在短回报；λ 越接近一，更多长回报进入目标。</p><h3 id="_1-4-资格迹是后向在线机制" tabindex="-1">1.4 资格迹是后向在线机制 <a class="header-anchor" href="#_1-4-资格迹是后向在线机制" aria-label="Permalink to &quot;1.4 资格迹是后向在线机制&quot;">​</a></h3><p>资格迹保存近期状态或参数参与预测的强度。每次出现时序差分误差，算法立即按痕迹大小更新相关价值，不必为每个历史状态重新向未来扫描完整轨迹。</p><p><img src="'+i+'" alt="从一步 TD 到蒙特卡洛之间存在完整的多步回报谱系"></p><h2 id="二、一步-td-为什么传播奖励较慢" tabindex="-1">二、一步 TD 为什么传播奖励较慢 <a class="header-anchor" href="#二、一步-td-为什么传播奖励较慢" aria-label="Permalink to &quot;二、一步 TD 为什么传播奖励较慢&quot;">​</a></h2><h3 id="_2-1-单次更新只连接相邻状态" tabindex="-1">2.1 单次更新只连接相邻状态 <a class="header-anchor" href="#_2-1-单次更新只连接相邻状态" aria-label="Permalink to &quot;2.1 单次更新只连接相邻状态&quot;">​</a></h3><p>TD(0) 的目标为：</p><p>$$ G_t^{(1)}=R_{t+1}+\\gamma V(S_{t+1}) $$</p><p>如果非终止步骤奖励全为零，只有终点给出正奖励，那么首次到达终点时，直接获得明确信号的通常只有终点前的状态。</p><h3 id="_2-2-更早状态依赖后续访问继续传递" tabindex="-1">2.2 更早状态依赖后续访问继续传递 <a class="header-anchor" href="#_2-2-更早状态依赖后续访问继续传递" aria-label="Permalink to &quot;2.2 更早状态依赖后续访问继续传递&quot;">​</a></h3><p>终点前状态价值升高后，下一回合再次经过相邻前驱，价值才可能继续向前移动。奖励像接力棒一样逐段传递，长链任务可能需要许多次访问才能影响较早决策。</p><h3 id="_2-3-稀疏奖励会放大传播距离问题" tabindex="-1">2.3 稀疏奖励会放大传播距离问题 <a class="header-anchor" href="#_2-3-稀疏奖励会放大传播距离问题" aria-label="Permalink to &quot;2.3 稀疏奖励会放大传播距离问题&quot;">​</a></h3><p>若一次成功需要连续完成感知、让行、换道和汇入，成功奖励与早期动作相隔很远。一步更新虽然在线且方差较低，却可能让早期动作长时间看不到有区分度的训练信号。</p><h2 id="三、n-步回报究竟计算什么" tabindex="-1">三、n 步回报究竟计算什么 <a class="header-anchor" href="#三、n-步回报究竟计算什么" aria-label="Permalink to &quot;三、n 步回报究竟计算什么&quot;">​</a></h2><h3 id="_3-1-收集-n-个真实奖励" tabindex="-1">3.1 收集 n 个真实奖励 <a class="header-anchor" href="#_3-1-收集-n-个真实奖励" aria-label="Permalink to &quot;3.1 收集 n 个真实奖励&quot;">​</a></h3><p>从时刻 (t) 出发，n 步回报先累加未来 n 个奖励，并按折扣因子逐步衰减：</p><p>$$ R_{t+1}+\\gamma R_{t+2}+\\cdots+\\gamma^{n-1}R_{t+n} $$</p><p>这些奖励来自实际采样轨迹，不是模型推演结果。</p><h3 id="_3-2-在第-n-步末端继续自举" tabindex="-1">3.2 在第 n 步末端继续自举 <a class="header-anchor" href="#_3-2-在第-n-步末端继续自举" aria-label="Permalink to &quot;3.2 在第 n 步末端继续自举&quot;">​</a></h3><p>若到达 (S_{t+n}) 时任务尚未自然终止，剩余未来由当前价值估计补上：</p><p>$$ G_t^{(n)}=R_{t+1}+\\gamma R_{t+2}+\\cdots+\\gamma^{n-1}R_{t+n}+\\gamma^nV(S_{t+n}) $$</p><h3 id="_3-3-更新仍然采用预测误差形式" tabindex="-1">3.3 更新仍然采用预测误差形式 <a class="header-anchor" href="#_3-3-更新仍然采用预测误差形式" aria-label="Permalink to &quot;3.3 更新仍然采用预测误差形式&quot;">​</a></h3><p>得到目标后，状态价值更新为：</p><p>$$ V(S_t)\\leftarrow V(S_t)+\\alpha\\left[G_t^{(n)}-V(S_t)\\right] $$</p><p>它仍属于时序差分方法，因为目标保留了末端价值估计，只是自举位置从一步之后移动到 n 步之后。</p><p><img src="'+l+'" alt="n 步回报由真实奖励段和末端自举值共同构成"></p><h2 id="四、一个数字例子怎样手算" tabindex="-1">四、一个数字例子怎样手算 <a class="header-anchor" href="#四、一个数字例子怎样手算" aria-label="Permalink to &quot;四、一个数字例子怎样手算&quot;">​</a></h2><h3 id="_4-1-给定四步奖励序列" tabindex="-1">4.1 给定四步奖励序列 <a class="header-anchor" href="#_4-1-给定四步奖励序列" aria-label="Permalink to &quot;4.1 给定四步奖励序列&quot;">​</a></h3><p>假设从 (S_t) 开始观察到奖励 (1)、(0)、(2)、(-1)，三步末端状态价值为 (4)，取 (\\gamma=0.9)。计算三步回报只使用前三个奖励和三步末端价值。</p><h3 id="_4-2-展开三步目标" tabindex="-1">4.2 展开三步目标 <a class="header-anchor" href="#_4-2-展开三步目标" aria-label="Permalink to &quot;4.2 展开三步目标&quot;">​</a></h3><p>目标为：</p><p>$$ G_t^{(3)}=1+0.9\\times0+0.9^2\\times2+0.9^3\\times4=5.536 $$</p><p>第四个奖励尚未直接进入这个三步目标，它的潜在影响由 (V(S_{t+3})) 的估计间接代表。</p><h3 id="_4-3-完成价值更新" tabindex="-1">4.3 完成价值更新 <a class="header-anchor" href="#_4-3-完成价值更新" aria-label="Permalink to &quot;4.3 完成价值更新&quot;">​</a></h3><p>若原来 (V(S_t)=4.0)，学习率 (\\alpha=0.1)，则误差为 (1.536)，更新后价值为 (4.1536)。手算时最常见错误是末端价值漏乘 (\\gamma^n)，或者把第 n 个奖励误写成 (\\gamma^nR_{t+n})。</p><h2 id="五、n-怎样连接-td-与蒙特卡洛" tabindex="-1">五、n 怎样连接 TD 与蒙特卡洛 <a class="header-anchor" href="#五、n-怎样连接-td-与蒙特卡洛" aria-label="Permalink to &quot;五、n 怎样连接 TD 与蒙特卡洛&quot;">​</a></h2><h3 id="_5-1-n-等于一时退化为-td-0" tabindex="-1">5.1 n 等于一时退化为 TD(0) <a class="header-anchor" href="#_5-1-n-等于一时退化为-td-0" aria-label="Permalink to &quot;5.1 n 等于一时退化为 TD(0)&quot;">​</a></h3><p>代入 (n=1)，目标只剩 (R_{t+1}+\\gamma V(S_{t+1}))。更新可以在一次转移后立即完成，存储和延迟都最小。</p><h3 id="_5-2-n-覆盖到终点时接近蒙特卡洛" tabindex="-1">5.2 n 覆盖到终点时接近蒙特卡洛 <a class="header-anchor" href="#_5-2-n-覆盖到终点时接近蒙特卡洛" aria-label="Permalink to &quot;5.2 n 覆盖到终点时接近蒙特卡洛&quot;">​</a></h3><p>若从 (t) 到终点只剩有限步，n 步窗口覆盖自然终止，末端价值定义为零，目标就成为实际完整回报。此时不再依赖终点之后的价值估计。</p><h3 id="_5-3-中间步长混合采样与自举" tabindex="-1">5.3 中间步长混合采样与自举 <a class="header-anchor" href="#_5-3-中间步长混合采样与自举" aria-label="Permalink to &quot;5.3 中间步长混合采样与自举&quot;">​</a></h3><p>较短 n 更依赖当前价值函数，通常目标方差较低；较长 n 使用更多真实奖励，通常减弱自举偏差，却暴露于更多随机事件。这里是偏差与方差的连续折中，而不是两个算法阵营的二选一。</p><h3 id="_5-4-折扣因子也在改变有效视野" tabindex="-1">5.4 折扣因子也在改变有效视野 <a class="header-anchor" href="#_5-4-折扣因子也在改变有效视野" aria-label="Permalink to &quot;5.4 折扣因子也在改变有效视野&quot;">​</a></h3><p>即使 n 很大，当 (\\gamma) 较小时，远期奖励与末端价值的权重已经非常小。讨论“传播十步”时必须同时报告 (\\gamma)，否则名义步长与实际影响范围可能相差很大。</p><h2 id="六、多步方法怎样加快奖励传播" tabindex="-1">六、多步方法怎样加快奖励传播 <a class="header-anchor" href="#六、多步方法怎样加快奖励传播" aria-label="Permalink to &quot;六、多步方法怎样加快奖励传播&quot;">​</a></h2><h3 id="_6-1-一步方法只直接强化末端前动作" tabindex="-1">6.1 一步方法只直接强化末端前动作 <a class="header-anchor" href="#_6-1-一步方法只直接强化末端前动作" aria-label="Permalink to &quot;6.1 一步方法只直接强化末端前动作&quot;">​</a></h3><p>在终点奖励为正、沿途奖励为零且初值为零的轨迹中，一步 Sarsa 首次看到终点后，只有最后一个动作的目标直接包含这份奖励。</p><h3 id="_6-2-n-步方法可强化末端前多个动作" tabindex="-1">6.2 n 步方法可强化末端前多个动作 <a class="header-anchor" href="#_6-2-n-步方法可强化末端前多个动作" aria-label="Permalink to &quot;6.2 n 步方法可强化末端前多个动作&quot;">​</a></h3><p>若使用十步回报，终点前十个动作的不同目标都可能包含终点奖励。单条成功轨迹由此向更长的历史片段传递信息，减少等待奖励逐回合向前扩散的时间。</p><h3 id="_6-3-传播更远不等于归因更准确" tabindex="-1">6.3 传播更远不等于归因更准确 <a class="header-anchor" href="#_6-3-传播更远不等于归因更准确" aria-label="Permalink to &quot;6.3 传播更远不等于归因更准确&quot;">​</a></h3><p>一条轨迹里可能混有关键动作、无关巡航和偶然环境变化。多步回报按时间距离传播结果，却不知道哪个动作在因果上真正决定成功，因此仍可能把偶然共现当作价值证据。</p><p><img src="'+h+'" alt="多步回报能在同一条成功轨迹中影响更早的状态动作"></p><h2 id="七、n-步-sarsa-怎样扩展控制" tabindex="-1">七、n 步 Sarsa 怎样扩展控制 <a class="header-anchor" href="#七、n-步-sarsa-怎样扩展控制" aria-label="Permalink to &quot;七、n 步 Sarsa 怎样扩展控制&quot;">​</a></h2><h3 id="_7-1-学习对象从状态价值换成动作价值" tabindex="-1">7.1 学习对象从状态价值换成动作价值 <a class="header-anchor" href="#_7-1-学习对象从状态价值换成动作价值" aria-label="Permalink to &quot;7.1 学习对象从状态价值换成动作价值&quot;">​</a></h3><p>n 步 Sarsa（n-step Sarsa，n 步状态—动作—奖励—状态—动作）使用动作价值目标：</p><p>$$ G_t^{(n)}=R_{t+1}+\\cdots+\\gamma^{n-1}R_{t+n}+\\gamma^nQ(S_{t+n},A_{t+n}) $$</p><p>末端动作 (A_{t+n}) 仍由当前行为策略实际选择，因此保留同策略语义。</p><h3 id="_7-2-更新会延迟-n-步" tabindex="-1">7.2 更新会延迟 n 步 <a class="header-anchor" href="#_7-2-更新会延迟-n-步" aria-label="Permalink to &quot;7.2 更新会延迟 n 步&quot;">​</a></h3><p>时刻 (t) 的目标必须等到 (R_{t+n})、(S_{t+n}) 和 (A_{t+n}) 已知后才能计算。在线交互仍然持续，但针对早期状态动作的写回存在固定延迟。</p><h3 id="_7-3-需要保存最近一段轨迹" tabindex="-1">7.3 需要保存最近一段轨迹 <a class="header-anchor" href="#_7-3-需要保存最近一段轨迹" aria-label="Permalink to &quot;7.3 需要保存最近一段轨迹&quot;">​</a></h3><p>实现通常用 Ring Buffer（环形缓冲区）保存最近的状态、动作和奖励，并按时间索引计算回报。缓存不必随回合无限增长，但至少要保留形成当前 n 步目标所需的元素。</p><h3 id="_7-4-回合结束后还要排空缓存" tabindex="-1">7.4 回合结束后还要排空缓存 <a class="header-anchor" href="#_7-4-回合结束后还要排空缓存" aria-label="Permalink to &quot;7.4 回合结束后还要排空缓存&quot;">​</a></h3><p>自然终止到来时，窗口中可能仍有尚未更新的早期状态动作。训练器需要逐个缩短剩余回报并完成尾部更新，否则每个回合最后若干状态动作会永久漏学。</p><h2 id="八、异策略多步学习为什么更难" tabindex="-1">八、异策略多步学习为什么更难 <a class="header-anchor" href="#八、异策略多步学习为什么更难" aria-label="Permalink to &quot;八、异策略多步学习为什么更难&quot;">​</a></h2><h3 id="_8-1-策略差异贯穿多段动作" tabindex="-1">8.1 策略差异贯穿多段动作 <a class="header-anchor" href="#_8-1-策略差异贯穿多段动作" aria-label="Permalink to &quot;8.1 策略差异贯穿多段动作&quot;">​</a></h3><p>一步 Q-learning 只在末端用贪心最大值定义目标，多步轨迹却包含行为策略连续采样的多个动作。行为策略与目标策略的概率差异会沿路径累积。</p><h3 id="_8-2-重要性采样比率可能高方差" tabindex="-1">8.2 重要性采样比率可能高方差 <a class="header-anchor" href="#_8-2-重要性采样比率可能高方差" aria-label="Permalink to &quot;8.2 重要性采样比率可能高方差&quot;">​</a></h3><p>一种修正思路是使用 Importance Sampling（重要性采样），把目标策略动作概率与行为策略动作概率的比值沿多步相乘。任一概率很小或策略差异较大，都可能让乘积接近零或异常巨大。</p><h3 id="_8-3-不能把-sarsa-末端项直接换成最大值就结束" tabindex="-1">8.3 不能把 Sarsa 末端项直接换成最大值就结束 <a class="header-anchor" href="#_8-3-不能把-sarsa-末端项直接换成最大值就结束" aria-label="Permalink to &quot;8.3 不能把 Sarsa 末端项直接换成最大值就结束&quot;">​</a></h3><p>多步异策略控制还要处理窗口内非目标策略动作的影响。Tree Backup（树回溯）、Expected Sarsa（期望 Sarsa）和 Q(σ) 等方法以不同方式混合采样与期望，不能用一行机械替换掩盖策略分布问题。</p><h3 id="_8-4-轨迹来自日志时必须知道行为策略" tabindex="-1">8.4 轨迹来自日志时必须知道行为策略 <a class="header-anchor" href="#_8-4-轨迹来自日志时必须知道行为策略" aria-label="Permalink to &quot;8.4 轨迹来自日志时必须知道行为策略&quot;">​</a></h3><p>若要严格计算策略概率比，需要知道采集动作在行为策略下的概率。只有状态和动作、没有行为策略概率的历史日志，无法直接提供完整的重要性采样信息。</p><h2 id="九、固定-n-为什么仍显得生硬" tabindex="-1">九、固定 n 为什么仍显得生硬 <a class="header-anchor" href="#九、固定-n-为什么仍显得生硬" aria-label="Permalink to &quot;九、固定 n 为什么仍显得生硬&quot;">​</a></h2><h3 id="_9-1-每个状态都被迫看同样远" tabindex="-1">9.1 每个状态都被迫看同样远 <a class="header-anchor" href="#_9-1-每个状态都被迫看同样远" aria-label="Permalink to &quot;9.1 每个状态都被迫看同样远&quot;">​</a></h3><p>固定 n 让拥堵巡航、紧急制动和接近终点的状态使用同一预测跨度，但不同事件的有效时间尺度可能并不相同。</p><h3 id="_9-2-选小-n-与选大-n-都会丢掉信息" tabindex="-1">9.2 选小 n 与选大 n 都会丢掉信息 <a class="header-anchor" href="#_9-2-选小-n-与选大-n-都会丢掉信息" aria-label="Permalink to &quot;9.2 选小 n 与选大 n 都会丢掉信息&quot;">​</a></h3><p>只选小 n 会忽略更长真实奖励序列，只选大 n 又放弃短期低方差目标。更自然的想法是同时利用多种步长，并让较长回报逐渐降低权重。</p><h3 id="_9-3-λ-回报提供连续加权方式" tabindex="-1">9.3 λ 回报提供连续加权方式 <a class="header-anchor" href="#_9-3-λ-回报提供连续加权方式" aria-label="Permalink to &quot;9.3 λ 回报提供连续加权方式&quot;">​</a></h3><p>TD(λ) 的前向视角不是挑选一个 n，而是把所有 n 步回报组合为单个目标。λ 控制权重沿步长方向衰减的速度。</p><h2 id="十、λ-回报怎样组合所有步长" tabindex="-1">十、λ 回报怎样组合所有步长 <a class="header-anchor" href="#十、λ-回报怎样组合所有步长" aria-label="Permalink to &quot;十、λ 回报怎样组合所有步长&quot;">​</a></h2><h3 id="_10-1-无限时域下的基本形式" tabindex="-1">10.1 无限时域下的基本形式 <a class="header-anchor" href="#_10-1-无限时域下的基本形式" aria-label="Permalink to &quot;10.1 无限时域下的基本形式&quot;">​</a></h3><p>λ 回报定义为：</p><p>$$ G_t^\\lambda=(1-\\lambda)\\sum_{n=1}^{\\infty}\\lambda^{n-1}G_t^{(n)} $$</p><p>一步回报权重为 (1-\\lambda)，两步回报权重为 ((1-\\lambda)\\lambda)，三步回报权重为 ((1-\\lambda)\\lambda^2)，依次衰减。</p><h3 id="_10-2-λ-等于零只保留一步目标" tabindex="-1">10.2 λ 等于零只保留一步目标 <a class="header-anchor" href="#_10-2-λ-等于零只保留一步目标" aria-label="Permalink to &quot;10.2 λ 等于零只保留一步目标&quot;">​</a></h3><p>当 (\\lambda=0) 时，只有一步回报权重不为零，TD(λ) 退化到 TD(0)。这也是名称中“零”的来源。</p><h3 id="_10-3-λ-接近一时强调长回报" tabindex="-1">10.3 λ 接近一时强调长回报 <a class="header-anchor" href="#_10-3-λ-接近一时强调长回报" aria-label="Permalink to &quot;10.3 λ 接近一时强调长回报&quot;">​</a></h3><p>λ 越大，权重衰减越慢，更多长期奖励进入目标。在有自然终止的回合中，剩余权重最终落到完整回报上；不能简单把有限回合公式截断后丢掉剩余权重。</p><h3 id="_10-4-λ-不是概率意义上的成功率" tabindex="-1">10.4 λ 不是概率意义上的成功率 <a class="header-anchor" href="#_10-4-λ-不是概率意义上的成功率" aria-label="Permalink to &quot;10.4 λ 不是概率意义上的成功率&quot;">​</a></h3><p>λ 是轨迹长度方向上的衰减参数，不代表探索率、终止概率或奖励可信度。它与 (\\gamma) 共同决定历史影响衰减，但两者职责不同。</p><p><img src="'+o+'" alt="λ 回报按指数权重混合不同长度的 n 步回报"></p><h2 id="十一、前向视角为什么适合理解" tabindex="-1">十一、前向视角为什么适合理解 <a class="header-anchor" href="#十一、前向视角为什么适合理解" aria-label="Permalink to &quot;十一、前向视角为什么适合理解&quot;">​</a></h2><h3 id="_11-1-从被更新状态向未来看" tabindex="-1">11.1 从被更新状态向未来看 <a class="header-anchor" href="#_11-1-从被更新状态向未来看" aria-label="Permalink to &quot;11.1 从被更新状态向未来看&quot;">​</a></h3><p>前向视角固定 (S_t)，收集后续奖励与价值，分别构造不同步长回报，再加权得到 (G_t^\\lambda)。它直接回答“这个状态后来发生了什么”。</p><h3 id="_11-2-目标定义清楚但在线计算困难" tabindex="-1">11.2 目标定义清楚但在线计算困难 <a class="header-anchor" href="#_11-2-目标定义清楚但在线计算困难" aria-label="Permalink to &quot;11.2 目标定义清楚但在线计算困难&quot;">​</a></h3><p>长回报依赖尚未发生的未来事件，完整 λ 回报还可能需要看到回合终点。若为每个历史状态分别保存并反复扫描未来轨迹，计算与存储都不够自然。</p><h3 id="_11-3-离线前向更新适合理论对照" tabindex="-1">11.3 离线前向更新适合理论对照 <a class="header-anchor" href="#_11-3-离线前向更新适合理论对照" aria-label="Permalink to &quot;11.3 离线前向更新适合理论对照&quot;">​</a></h3><p>在完整轨迹已知、价值参数暂时固定时，可以显式算出各步回报和 λ 回报，用作手算、单元测试或验证后向实现的参考答案。</p><h2 id="十二、资格迹怎样建立后向视角" tabindex="-1">十二、资格迹怎样建立后向视角 <a class="header-anchor" href="#十二、资格迹怎样建立后向视角" aria-label="Permalink to &quot;十二、资格迹怎样建立后向视角&quot;">​</a></h2><h3 id="_12-1-每个状态维护短期记忆" tabindex="-1">12.1 每个状态维护短期记忆 <a class="header-anchor" href="#_12-1-每个状态维护短期记忆" aria-label="Permalink to &quot;12.1 每个状态维护短期记忆&quot;">​</a></h3><p>表格型状态价值可以为每个状态维护痕迹 (E_t(s))。回合开始时全部清零，访问当前状态时增加痕迹，随后旧痕迹按 (\\gamma\\lambda) 衰减：</p><p>$$ E_t(s)=\\gamma\\lambda E_{t-1}(s)+\\mathbb{I}(S_t=s) $$</p><h3 id="_12-2-当前误差按痕迹分配给历史状态" tabindex="-1">12.2 当前误差按痕迹分配给历史状态 <a class="header-anchor" href="#_12-2-当前误差按痕迹分配给历史状态" aria-label="Permalink to &quot;12.2 当前误差按痕迹分配给历史状态&quot;">​</a></h3><p>每步先计算普通一步时序差分误差：</p><p>$$ \\delta_t=R_{t+1}+\\gamma V(S_{t+1})-V(S_t) $$</p><p>再对所有具有非零痕迹的状态更新：</p><p>$$ V(s)\\leftarrow V(s)+\\alpha\\delta_tE_t(s) $$</p><h3 id="_12-3-越近且越常访问通常痕迹越强" tabindex="-1">12.3 越近且越常访问通常痕迹越强 <a class="header-anchor" href="#_12-3-越近且越常访问通常痕迹越强" aria-label="Permalink to &quot;12.3 越近且越常访问通常痕迹越强&quot;">​</a></h3><p>刚访问的状态获得新增痕迹，较早状态不断衰减。若一个状态短期内反复出现，累积型痕迹还会叠加访问次数，因此同时包含 Recency（近因性）和 Frequency（频率）两类启发。</p><h3 id="_12-4-不必等待-n-步后再集中更新" tabindex="-1">12.4 不必等待 n 步后再集中更新 <a class="header-anchor" href="#_12-4-不必等待-n-步后再集中更新" aria-label="Permalink to &quot;12.4 不必等待 n 步后再集中更新&quot;">​</a></h3><p>当前误差一出现，就可以沿痕迹立即影响近期状态。计算由“为早期状态等待未来”改成“用现在的误差回看过去”，更新负担更加均匀。</p><p><img src="'+s+'" alt="当前 TD 误差通过衰减资格迹分配给近期状态"></p><h2 id="十三、前向与后向视角是否完全等价" tabindex="-1">十三、前向与后向视角是否完全等价 <a class="header-anchor" href="#十三、前向与后向视角是否完全等价" aria-label="Permalink to &quot;十三、前向与后向视角是否完全等价&quot;">​</a></h2><h3 id="_13-1-离线固定价值时可以建立严格关系" tabindex="-1">13.1 离线固定价值时可以建立严格关系 <a class="header-anchor" href="#_13-1-离线固定价值时可以建立严格关系" aria-label="Permalink to &quot;13.1 离线固定价值时可以建立严格关系&quot;">​</a></h3><p>经典推导在一个回合内保持用于目标的价值不变，并在回合结束后汇总更新时，前向 λ 回报与后向累积痕迹的总更新可以对应起来。这是理解 TD(λ) 的核心桥梁。</p><h3 id="_13-2-普通在线更新会改变后续目标" tabindex="-1">13.2 普通在线更新会改变后续目标 <a class="header-anchor" href="#_13-2-普通在线更新会改变后续目标" aria-label="Permalink to &quot;13.2 普通在线更新会改变后续目标&quot;">​</a></h3><p>若每一步立即修改价值，未来构造 λ 回报时使用的参数已经变化。传统在线 TD(λ) 通常近似离线前向视角，而不是在任意学习率下逐步完全相同。</p><h3 id="_13-3-true-online-td-λ-修正在线差异" tabindex="-1">13.3 True Online TD(λ) 修正在线差异 <a class="header-anchor" href="#_13-3-true-online-td-λ-修正在线差异" aria-label="Permalink to &quot;13.3 True Online TD(λ) 修正在线差异&quot;">​</a></h3><p>True Online TD(λ)（真正在线 TD(λ)）通过 Dutch Trace（荷兰迹）和额外校正项，对应一种在线前向视角。初学阶段应先掌握普通累积痕迹，再理解为什么“前后向等价”需要说明具体算法与更新时机。</p><h2 id="十四、累积迹与替换迹有什么区别" tabindex="-1">十四、累积迹与替换迹有什么区别 <a class="header-anchor" href="#十四、累积迹与替换迹有什么区别" aria-label="Permalink to &quot;十四、累积迹与替换迹有什么区别&quot;">​</a></h2><h3 id="_14-1-累积迹会叠加重复访问" tabindex="-1">14.1 累积迹会叠加重复访问 <a class="header-anchor" href="#_14-1-累积迹会叠加重复访问" aria-label="Permalink to &quot;14.1 累积迹会叠加重复访问&quot;">​</a></h3><p>Accumulating Trace（累积迹）在每次访问时加一。循环轨迹中同一状态反复出现，痕迹可能超过一，使当前误差对该状态产生更强更新。</p><h3 id="_14-2-替换迹把当前状态设为一" tabindex="-1">14.2 替换迹把当前状态设为一 <a class="header-anchor" href="#_14-2-替换迹把当前状态设为一" aria-label="Permalink to &quot;14.2 替换迹把当前状态设为一&quot;">​</a></h3><p>Replacing Trace（替换迹）常把当前访问状态的痕迹直接设为一，而不是继续叠加。它可以限制频繁重复访问造成的痕迹膨胀，但具体形式与表格或函数逼近设置有关。</p><h3 id="_14-3-两者不是无关紧要的实现细节" tabindex="-1">14.3 两者不是无关紧要的实现细节 <a class="header-anchor" href="#_14-3-两者不是无关紧要的实现细节" aria-label="Permalink to &quot;14.3 两者不是无关紧要的实现细节&quot;">​</a></h3><p>在无重复状态的短轨迹上，两者表现可能相同；在循环和高频访问任务中，更新尺度会明显不同。实验记录必须写明痕迹类型，而不是只报告 λ。</p><h2 id="十五、sarsa-λ-怎样用于动作价值" tabindex="-1">十五、Sarsa(λ) 怎样用于动作价值 <a class="header-anchor" href="#十五、sarsa-λ-怎样用于动作价值" aria-label="Permalink to &quot;十五、Sarsa(λ) 怎样用于动作价值&quot;">​</a></h2><h3 id="_15-1-痕迹从状态扩展到状态动作对" tabindex="-1">15.1 痕迹从状态扩展到状态动作对 <a class="header-anchor" href="#_15-1-痕迹从状态扩展到状态动作对" aria-label="Permalink to &quot;15.1 痕迹从状态扩展到状态动作对&quot;">​</a></h3><p>Sarsa(λ) 为 (E_t(s,a)) 维护资格迹。当前实际执行的 ((S_t,A_t)) 增加痕迹，时序差分误差仍使用行为策略实际选择的下一动作。</p><h3 id="_15-2-当前误差会更新近期多组动作" tabindex="-1">15.2 当前误差会更新近期多组动作 <a class="header-anchor" href="#_15-2-当前误差会更新近期多组动作" aria-label="Permalink to &quot;15.2 当前误差会更新近期多组动作&quot;">​</a></h3><p>每步误差按各状态动作痕迹写回 (Q(s,a))。因此一次迟到奖励可以在同一步影响沿途多个动作价值，而不只更新最近动作。</p><h3 id="_15-3-watkins-q-λ-需要切断非贪心轨迹" tabindex="-1">15.3 Watkins Q(λ) 需要切断非贪心轨迹 <a class="header-anchor" href="#_15-3-watkins-q-λ-需要切断非贪心轨迹" aria-label="Permalink to &quot;15.3 Watkins Q(λ) 需要切断非贪心轨迹&quot;">​</a></h3><p>把资格迹加入异策略 Q-learning 时，若行为策略选择了非贪心动作，后续轨迹不再完全符合贪心目标策略。经典 Watkins Q(λ)（沃特金斯 Q(λ)）会在此类动作后清除或截断痕迹，不能把 Sarsa(λ) 的后向循环原样套用。</p><h3 id="_15-4-安全过滤器也会改变行为语义" tabindex="-1">15.4 安全过滤器也会改变行为语义 <a class="header-anchor" href="#_15-4-安全过滤器也会改变行为语义" aria-label="Permalink to &quot;15.4 安全过滤器也会改变行为语义&quot;">​</a></h3><p>若策略给出动作后被安全层替换，实际执行动作与策略提议动作不同。资格迹应记录谁、价值目标在评估谁、奖励归因给哪一层决策，都必须显式定义。</p><h2 id="十六、终止、截断和持续任务怎样处理" tabindex="-1">十六、终止、截断和持续任务怎样处理 <a class="header-anchor" href="#十六、终止、截断和持续任务怎样处理" aria-label="Permalink to &quot;十六、终止、截断和持续任务怎样处理&quot;">​</a></h2><h3 id="_16-1-自然终止后自举项为零" tabindex="-1">16.1 自然终止后自举项为零 <a class="header-anchor" href="#_16-1-自然终止后自举项为零" aria-label="Permalink to &quot;16.1 自然终止后自举项为零&quot;">​</a></h3><p>当 n 步窗口跨过真正终点，终点之后不存在奖励和状态价值。回报只累计到终点，并把缺失的末端自举设为零。</p><h3 id="_16-2-时间限制截断不必清空未来价值" tabindex="-1">16.2 时间限制截断不必清空未来价值 <a class="header-anchor" href="#_16-2-时间限制截断不必清空未来价值" aria-label="Permalink to &quot;16.2 时间限制截断不必清空未来价值&quot;">​</a></h3><p>若回合只是被训练时长或日志切片截断，任务动力学可能仍会继续。是否自举应依据接口中的终止语义，而不是把所有 <code>done</code> 都当作自然终止。</p><h3 id="_16-3-回合边界通常要重置痕迹" tabindex="-1">16.3 回合边界通常要重置痕迹 <a class="header-anchor" href="#_16-3-回合边界通常要重置痕迹" aria-label="Permalink to &quot;16.3 回合边界通常要重置痕迹&quot;">​</a></h3><p>独立回合之间没有连续信用关系，资格迹应清零。若忘记重置，上个场景末尾的误差会污染下个场景开头。</p><h3 id="_16-4-持续任务不能依赖回合排空" tabindex="-1">16.4 持续任务不能依赖回合排空 <a class="header-anchor" href="#_16-4-持续任务不能依赖回合排空" aria-label="Permalink to &quot;16.4 持续任务不能依赖回合排空&quot;">​</a></h3><p>Continuing Task（持续任务）没有自然终点，多步实现需要稳定的滚动窗口，资格迹则可以持续衰减并在线更新。此时平均奖励或折扣任务定义也要与算法一致。</p><h2 id="十七、自动驾驶中的价值与边界" tabindex="-1">十七、自动驾驶中的价值与边界 <a class="header-anchor" href="#十七、自动驾驶中的价值与边界" aria-label="Permalink to &quot;十七、自动驾驶中的价值与边界&quot;">​</a></h2><h3 id="_17-1-多步回报适合描述控制时延" tabindex="-1">17.1 多步回报适合描述控制时延 <a class="header-anchor" href="#_17-1-多步回报适合描述控制时延" aria-label="Permalink to &quot;17.1 多步回报适合描述控制时延&quot;">​</a></h3><p>转向命令的效果可能若干周期后才体现在横向误差和航向误差上。适度多步目标能把后续轨迹质量反馈给较早控制动作，比只看下一周期更接近控制链实际响应时间。</p><h3 id="_17-2-资格迹可传递迟到的风险信号" tabindex="-1">17.2 资格迹可传递迟到的风险信号 <a class="header-anchor" href="#_17-2-资格迹可传递迟到的风险信号" aria-label="Permalink to &quot;17.2 资格迹可传递迟到的风险信号&quot;">​</a></h3><p>车辆最终越界时，近期一连串转向动作都可能获得负向更新。这有助于传播风险信息，却不能证明这些动作在真实因果链上承担相同责任。</p><h3 id="_17-3-过长痕迹可能跨越场景机制变化" tabindex="-1">17.3 过长痕迹可能跨越场景机制变化 <a class="header-anchor" href="#_17-3-过长痕迹可能跨越场景机制变化" aria-label="Permalink to &quot;17.3 过长痕迹可能跨越场景机制变化&quot;">​</a></h3><p>交通灯切换、道路曲率突变、目标车插入或控制模式切换会改变动力学和奖励含义。若痕迹跨过这些边界，旧状态可能收到来自新机制的误差。</p><h3 id="_17-4-安全约束不能由信用分配替代" tabindex="-1">17.4 安全约束不能由信用分配替代 <a class="header-anchor" href="#_17-4-安全约束不能由信用分配替代" aria-label="Permalink to &quot;17.4 安全约束不能由信用分配替代&quot;">​</a></h3><p>资格迹改善的是学习信号传播，不提供碰撞避免、车道约束或最小安全距离保证。Control Barrier Function（控制屏障函数）、动作屏蔽和独立监控器仍需单独设计和验证。</p><h2 id="十八、一个最小实验应该怎样设计" tabindex="-1">十八、一个最小实验应该怎样设计 <a class="header-anchor" href="#十八、一个最小实验应该怎样设计" aria-label="Permalink to &quot;十八、一个最小实验应该怎样设计&quot;">​</a></h2><h3 id="_18-1-从随机游走预测开始" tabindex="-1">18.1 从随机游走预测开始 <a class="header-anchor" href="#_18-1-从随机游走预测开始" aria-label="Permalink to &quot;18.1 从随机游走预测开始&quot;">​</a></h3><p>使用有限状态 Random Walk（随机游走），两端自然终止，中间奖励稀疏。对比不同 n 和 λ 下的价值均方根误差，可以先隔离策略改进与探索带来的干扰。</p><h3 id="_18-2-再进入带延迟奖励的网格控制" tabindex="-1">18.2 再进入带延迟奖励的网格控制 <a class="header-anchor" href="#_18-2-再进入带延迟奖励的网格控制" aria-label="Permalink to &quot;18.2 再进入带延迟奖励的网格控制&quot;">​</a></h3><p>保持环境、策略、奖励、学习率和随机种子一致，对比一步 Sarsa、n 步 Sarsa 与 Sarsa(λ)。记录到达成功、路径长度、训练回报和状态动作覆盖。</p><h3 id="_18-3-联合扫描学习率和传播参数" tabindex="-1">18.3 联合扫描学习率和传播参数 <a class="header-anchor" href="#_18-3-联合扫描学习率和传播参数" aria-label="Permalink to &quot;18.3 联合扫描学习率和传播参数&quot;">​</a></h3><p>n 或 λ 改变目标尺度与方差，最佳学习率也可能随之改变。固定一个只对 TD(0) 友好的学习率，再比较其他方法，会得到不公平结论。</p><h3 id="_18-4-观察传播范围而不只看最终回报" tabindex="-1">18.4 观察传播范围而不只看最终回报 <a class="header-anchor" href="#_18-4-观察传播范围而不只看最终回报" aria-label="Permalink to &quot;18.4 观察传播范围而不只看最终回报&quot;">​</a></h3><p>保存单条成功轨迹前后的价值变化，直接检查多少个早期状态动作得到更新。再使用多随机种子统计性能，避免把一次幸运传播误判为稳定优势。</p><h2 id="十九、实现与理解中的常见错误" tabindex="-1">十九、实现与理解中的常见错误 <a class="header-anchor" href="#十九、实现与理解中的常见错误" aria-label="Permalink to &quot;十九、实现与理解中的常见错误&quot;">​</a></h2><h3 id="_19-1-把-n-理解成训练回合数" tabindex="-1">19.1 把 n 理解成训练回合数 <a class="header-anchor" href="#_19-1-把-n-理解成训练回合数" aria-label="Permalink to &quot;19.1 把 n 理解成训练回合数&quot;">​</a></h3><p>n 表示单个更新目标向未来看的转移步数，与训练多少回合无关。一个回合中会形成许多彼此重叠的 n 步窗口。</p><h3 id="_19-2-折扣指数发生一位偏移" tabindex="-1">19.2 折扣指数发生一位偏移 <a class="header-anchor" href="#_19-2-折扣指数发生一位偏移" aria-label="Permalink to &quot;19.2 折扣指数发生一位偏移&quot;">​</a></h3><p>(R_{t+k}) 的权重应为 (\\gamma^{k-1})，末端价值权重为 (\\gamma^n)。索引偏移会让手算、缓存和代码结果全部不一致。</p><h3 id="_19-3-终止后仍查询价值或动作" tabindex="-1">19.3 终止后仍查询价值或动作 <a class="header-anchor" href="#_19-3-终止后仍查询价值或动作" aria-label="Permalink to &quot;19.3 终止后仍查询价值或动作&quot;">​</a></h3><p>自然终止后的状态没有真实后续动作价值。n 步 Sarsa 不应为终止状态虚构 (A_{t+n})，资格迹也不应跨独立回合保留。</p><h3 id="_19-4-忘记排空回合尾部窗口" tabindex="-1">19.4 忘记排空回合尾部窗口 <a class="header-anchor" href="#_19-4-忘记排空回合尾部窗口" aria-label="Permalink to &quot;19.4 忘记排空回合尾部窗口&quot;">​</a></h3><p>只在缓存长度达到 n 时更新，会遗漏终点前不足 n 步的状态动作。正确实现需要在终止后继续完成所有待处理目标。</p><h3 id="_19-5-声称-λ-越大信用分配越准确" tabindex="-1">19.5 声称 λ 越大信用分配越准确 <a class="header-anchor" href="#_19-5-声称-λ-越大信用分配越准确" aria-label="Permalink to &quot;19.5 声称 λ 越大信用分配越准确&quot;">​</a></h3><p>更长痕迹只表示误差传播更远，也会把更多随机事件和无关历史纳入更新。准确性必须通过任务指标和估计误差验证，不能从参数大小推导。</p><h3 id="_19-6-把前后向等价写成无条件定理" tabindex="-1">19.6 把前后向等价写成无条件定理 <a class="header-anchor" href="#_19-6-把前后向等价写成无条件定理" aria-label="Permalink to &quot;19.6 把前后向等价写成无条件定理&quot;">​</a></h3><p>离线、在线、函数逼近、痕迹类型和参数更新时机都会影响等价关系。技术文章和代码注释必须说明采用哪一种 TD(λ)，而不是只写一个算法名。</p><p>学完这一篇，应该能够从一条轨迹手算 n 步回报和 λ 权重，解释资格迹怎样用当前误差更新近期状态，区分累积迹与替换迹，并指出异策略控制、终止处理和真实车辆安全中的额外边界。</p><p>下一篇将从表格型价值方法走向 Function Approximation（函数逼近）：状态数量为什么会爆炸，线性价值函数怎样共享经验，以及把动作价值交给神经网络之前必须解决哪些稳定性问题。</p><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter3/chapter3.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第 3 章：n 步 Sarsa、Sarsa(λ) 与资格迹衰减参数</a></p><p><a href="https://web.stanford.edu/class/psych209/Readings/SuttonBartoIPRLBook2ndEd.pdf" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction（强化学习导论）》第 7 章：n 步回报与多步自举</a></p><p><a href="https://web.stanford.edu/class/psych209/Readings/SuttonBartoIPRLBook2ndEd.pdf" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction（强化学习导论）》第 12 章：λ 回报、资格迹与 TD(λ)</a></p><p><a href="https://davidstarsilver.wordpress.com/wp-content/uploads/2025/04/lecture-4-model-free-prediction-.pdf" target="_blank" rel="noreferrer">David Silver 强化学习课程第 4 讲：Model-Free Prediction（免模型预测）与 TD(λ)</a></p><p><a href="https://ojs.aaai.org/index.php/AAAI/article/view/17200" target="_blank" rel="noreferrer">van Hasselt 等人的 Expected Eligibility Traces（期望资格迹）论文：信用分配与资格迹扩展</a></p>',192)])])}const k=e(d,[["render",p]]);export{f as __pageData,k as default};
